/*
 * Runtime for the code generated by tools/py2c.py.
 *
 * The generated functions are statement-by-statement translations of the methods of
 * python-openhab-rest-client. Python values are cJSON values here. Every temporary
 * value belongs to the pool of the call context and is freed when the call returns;
 * values that are put into a container are copied, so nothing is freed twice.
 * Exceptions of the HTTP client (HTTPError, RequestException) are kept in the context.
 */
#ifndef PY_RT_H
#define PY_RT_H

#include "oh_internal.h"

typedef struct py_ctx {
    openhab_client_t* client;
    cJSON* pool;        /* owns all temporary values */
    int exc;            /* 0 = none, 1 = HTTPError, 2 = RequestException */
    int status;         /* err.response.status_code */
    char msg[1100];     /* str(err) */
} py_ctx;

void py_init(py_ctx* X, openhab_client_t* c);
/* Returns a copy of result owned by the caller (or an error object for an uncaught
 * exception) and frees the pool. */
cJSON* py_finish(py_ctx* X, cJSON* result);
/* For stream methods: turns a non-stream result into a stream object. */
openhab_sse_t* py_finish_stream(py_ctx* X, openhab_sse_t* s, cJSON* result);

cJSON* py_keep(py_ctx* X, cJSON* v);
cJSON* py_none(py_ctx* X);
cJSON* py_bool(py_ctx* X, int b);
cJSON* py_num(py_ctx* X, double d);
cJSON* py_s(py_ctx* X, const char* s);          /* new str (NULL -> None) */
cJSON* py_arg_flag(py_ctx* X, openhab_flag f, cJSON* dflt);
cJSON* py_arg_json(py_ctx* X, const cJSON* v);  /* copy of a cJSON argument (NULL -> None) */

int py_truthy(const cJSON* v);
int py_isnone(const cJSON* v);
int py_eq(const cJSON* a, const cJSON* b);
int py_cmp(const cJSON* a, const cJSON* b);
int py_contains(const cJSON* container, const cJSON* x);
cJSON* py_or(cJSON* a, cJSON* b);
cJSON* py_and(cJSON* a, cJSON* b);

cJSON* py_str(py_ctx* X, const cJSON* v);       /* str(v) */
cJSON* py_cat(py_ctx* X, int n, ...);            /* f-string: str() of all parts joined */
cJSON* py_lower(py_ctx* X, const cJSON* s);
cJSON* py_strip(py_ctx* X, const cJSON* s);
cJSON* py_rstrip(py_ctx* X, const cJSON* s, const cJSON* chars);
cJSON* py_split(py_ctx* X, const cJSON* s, const cJSON* sep);
cJSON* py_join(py_ctx* X, const cJSON* sep, const cJSON* items);
int py_len(const cJSON* v);

int py_isdict(const cJSON* v);
int py_islist(const cJSON* v);
int py_isstr(const cJSON* v);
int py_isbool(const cJSON* v);
int py_isstatus(const cJSON* v);

cJSON* py_dict(py_ctx* X, int n, ...);           /* n pairs: const char* key, cJSON* value */
cJSON* py_list(py_ctx* X, int n, ...);
cJSON* py_copy(py_ctx* X, const cJSON* m);
cJSON* py_without_none(py_ctx* X, const cJSON* m);
cJSON* py_get(py_ctx* X, const cJSON* obj, const cJSON* key);
cJSON* py_getor(py_ctx* X, const cJSON* obj, const cJSON* key, cJSON* dflt);
void py_set(py_ctx* X, cJSON* obj, const cJSON* key, const cJSON* value);

cJSON* py_quote(py_ctx* X, const cJSON* s, const char* safe);
cJSON* py_urlencode(py_ctx* X, const cJSON* params);
cJSON* py_dumps(py_ctx* X, const cJSON* v);

/* self.client.get/post/put/delete – NULL with X->exc set on an exception */
cJSON* py_http(py_ctx* X, const char* verb, const cJSON* path, const cJSON* headers,
               const cJSON* data, const cJSON* params);
/* err.response.status_code and str(err) */
cJSON* py_exc_status(py_ctx* X);
cJSON* py_exc_str(py_ctx* X);
void py_clear_exc(py_ctx* X);

/* _openStream(client, topics, path, headers, errors) of Events.py */
openhab_sse_t* py_open_stream(py_ctx* X, const cJSON* topics, const cJSON* path,
                              const cJSON* headers, const cJSON* errors);

/* client.executeSSE: NULL with X->exc set if the stream could not be opened */
openhab_sse_t* py_sse(py_ctx* X, const cJSON* path, const cJSON* headers, const cJSON* params);
/* returning {"error": ...} from a stream method: a stream that carries the error */
openhab_sse_t* py_as_stream(py_ctx* X, cJSON* v);

#endif
